{"code":"import pandas as pd, numpy as np, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); cols=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
for c in cols:
 d=x[['yield_kg','farm',c]].dropna(); m=smf.ols(f'yield_kg ~ {c} + C(farm)',d).fit()
 print(c, len(d), round(m.params[c],3), round(m.pvalues[c],5), round(m.rsquared,3))"}
